do $$
declare
  table_name text;
begin
  foreach table_name in array array[
    'level_definitions',
    'badge_definitions',
    'badge_requirement_definitions',
    'virtue_definitions',
    'saint_definitions',
    'demon_definitions',
    'demon_attacks',
    'demon_defenses',
    'challenge_definitions'
  ]
  loop
    execute format(
      'alter table competition.%I add column if not exists translations jsonb not null default ''{}''::jsonb',
      table_name
    );
    execute format(
      'alter table competition.%I drop constraint if exists %I',
      table_name,
      table_name || '_translations_check'
    );
    execute format(
      'alter table competition.%I add constraint %I check (
        jsonb_typeof(translations) = ''object''
        and translations - ''es'' = ''{}''::jsonb
        and (not (translations ? ''es'') or jsonb_typeof(translations -> ''es'') = ''object'')
      )',
      table_name,
      table_name || '_translations_check'
    );
  end loop;
end
$$;

alter table app.examination_of_conscience_questions
  add column if not exists translations jsonb not null default '{}'::jsonb;
alter table app.examination_of_conscience_questions
  drop constraint if exists examination_of_conscience_questions_translations_check;
alter table app.examination_of_conscience_questions
  add constraint examination_of_conscience_questions_translations_check check (
    jsonb_typeof(translations) = 'object'
    and translations - 'es' = '{}'::jsonb
    and (not (translations ? 'es') or jsonb_typeof(translations -> 'es') = 'object')
  );

create or replace function platform.apply_spanish_catalog_translations()
returns void
language plpgsql
set search_path = ''
as $$
begin
  update competition.level_definitions as target
  set translations = jsonb_set(target.translations, '{es}', source.value, true)
