    ('awakened', jsonb_build_object('name', 'Despierto', 'description', 'Comienza a reconocer la batalla.')),
    ('seeker', jsonb_build_object('name', 'Buscador', 'description', 'Comienza a formar hábitos diarios.')),
    ('disciple', jsonb_build_object('name', 'Discípulo', 'description', 'Sigue una regla de vida constante.')),
    ('fighter', jsonb_build_object('name', 'Luchador', 'description', 'Resiste las tentaciones recurrentes.')),
    ('guardian', jsonb_build_object('name', 'Guardián', 'description', 'Protege su entorno y sus relaciones.')),
    ('servant', jsonb_build_object('name', 'Servidor', 'description', 'Sirve a los demás con regularidad.')),
    ('brother', jsonb_build_object('name', 'Hermano', 'description', 'Apoya a otros hombres.')),
