    ('SHIELD_OF_FAITH', jsonb_build_object('name', 'Escudo de la fe', 'description', 'Desbloquea el Escudo de la fe mediante la oración constante, la Escritura y la confianza en las dificultades.', 'rules', jsonb_build_object('virtue', 'faith', 'requirements', jsonb_build_array(jsonb_build_object('type', 'prayer_days', 'value', 7, 'description', 'Siete días de oración'), jsonb_build_object('type', 'scripture_plan_completed', 'value', 1, 'description', 'Un plan de lectura de la Escritura completado'), jsonb_build_object('type', 'trust_act_during_difficulty', 'value', 1, 'description', 'Un acto de confianza durante una dificultad'))))),
    ('SWORD_OF_THE_SPIRIT', jsonb_build_object('name', 'Espada del Espíritu', 'description', 'Desbloquea la Espada del Espíritu guardando la Palabra de Dios en tu corazón.')),
    ('HELMET_OF_SALVATION', jsonb_build_object('name', 'Yelmo de la salvación', 'description', 'Desbloquea el Yelmo de la salvación renovando la esperanza y protegiendo tu mente.')),
