    ('PRAYER_INTENTION_1', jsonb_build_object('name', 'Primera intención', 'description', 'Comparte una intención de oración comunitaria aprobada por un administrador.')),
    ('PRAYER_INTENTION_3', jsonb_build_object('name', 'Intercesor fiel', 'description', 'Comparte tres intenciones de oración comunitaria aprobadas por un administrador.')),
    ('PRAYER_INTENTION_7', jsonb_build_object('name', 'Defensor de la oración', 'description', 'Comparte siete intenciones de oración comunitaria aprobadas por un administrador.'))
