    ('SCROLLZILLA', jsonb_build_object('name', 'Scrollzilla', 'title', 'El desplazador interminable', 'description', 'Una diminuta molestia roja con pulgares enormes que se alimenta de notificaciones, videos cortos y de posponer la hora de dormir.', 'silly_personality', 'Carga tres teléfonos, pero nunca recuerda dónde dejó ninguno.', 'saint_mentor_reason', 'El discernimiento y la atención ordenada revelan los trucos de Scrollzilla.')),
